package org.sleepwell.app;
import android.content.*;import androidx.test.platform.app.InstrumentationRegistry;import java.time.*;import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
/** Actual measurement storage, never a service or hardware admission. Named databases only. */
public final class RecordAchievementsStorageTest {
 static final long HOUR=3600000L,NOW=Instant.parse("2026-10-28T18:00:00Z").toEpochMilli();
 static long motion(Store s,String start,int minutes){long wall=Instant.parse(start).toEpochMilli(),id=s.begin();ContentValues v=new ContentValues();v.put("start",wall);v.put("zone","UTC");s.getWritableDatabase().update("sessions",v,"id=?",new String[]{""+id});for(int n=0;n<minutes;n++)s.checkpoint(id,wall+n*60000,wall+(n+1)*60000,0d,null,null,100,(n+1)*60000L,true);s.end(id,false,minutes*60000L,wall+minutes*60000L);return id;}
 @Test public void savedCoverageRecalculatesAfterActualTrimAndDeletionWithoutChangingRawEvidence()throws Exception{Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();String name="achievements-storage-"+UUID.randomUUID();try(Store s=new Store(c,name)){long id=motion(s,"2026-10-20T00:00:00Z",240);Records.create(s,new RecordDraft(Instant.parse("2026-10-21T00:00:00Z").toEpochMilli(),Instant.parse("2026-10-21T08:00:00Z").toEpochMilli()),ZoneOffset.UTC,NOW);String before=s.backup().toString();RecordAchievements result=RecordAchievementsReader.read(s,NOW);assertEquals(1,result.count);assertEquals(4*HOUR,result.millis);assertEquals(before,s.backup().toString());RecordEntry r=Records.get(s,id);RecordDraft edit=r.edit.copy();edit.start+=2*HOUR;Records.save(s,id,edit,r.updated,NOW);assertEquals(0,RecordAchievementsReader.read(s,NOW).count);assertEquals(240,s.rows("SELECT id FROM epochs WHERE session=?",""+id).size());assertEquals(r.rawStart,Records.get(s,id).rawStart);Records.reset(s,id,Records.get(s,id).updated);assertEquals(1,RecordAchievementsReader.read(s,NOW).count);Records.delete(s,id,Records.get(s,id).updated);assertEquals(0,RecordAchievementsReader.read(s,NOW).count);}finally{c.deleteDatabase(name);}}
 @Test public void realSonarZeroValidSignalQualifiesButNullQualityGapDoesNot()throws Exception{Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();String name="achievements-sonar-"+UUID.randomUUID();long start=Instant.parse("2026-10-20T00:00:00Z").toEpochMilli();try(Store s=new Store(c,name)){long id=s.begin(SensorProvenance.SONAR,SensorProvenance.sonar(SonarConfig.defaults(),"UNPROCESSED"));ContentValues v=new ContentValues();v.put("start",start);v.put("zone","UTC");s.getWritableDatabase().update("sessions",v,"id=?",new String[]{""+id});s.getWritableDatabase().beginTransaction();try{for(int n=0;n<2160;n++)s.sonarCheckpoint(id,start+n*5000,start+(n+1)*5000,0d,"VALID",20,(n+1)*5000L);s.getWritableDatabase().setTransactionSuccessful();}finally{s.getWritableDatabase().endTransaction();}s.sonarCheckpoint(id,start+3*HOUR,start+3*HOUR+5000,null,"NO_ECHO",20,3*HOUR+5000);s.end(id,false,3*HOUR+5000,start+3*HOUR+5000);String before=s.backup().toString();assertEquals(1,RecordAchievementsReader.read(s,NOW).count);assertEquals(3*HOUR,RecordAchievementsReader.read(s,NOW).millis);assertEquals(before,s.backup().toString());s.getWritableDatabase().execSQL("UPDATE epochs SET movement=NULL,signal_quality='NO_ECHO' WHERE session=? AND start=?",new Object[]{id,start});assertEquals(0,RecordAchievementsReader.read(s,NOW).count);}finally{c.deleteDatabase(name);}}
}
